package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时钟配置：业务时间统一走 Clock（UTC），测试中可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    /**
     * 系统UTC时钟。
     */
    @Bean
    public Clock businessClock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.water;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态与稳定错误码，由全局异常处理器转换为响应体。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    /**
     * 404 资源不存在。
     */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }

    /**
     * 409 幂等冲突：同 requestId 但指纹不同。
     */
    public static ApiException idempotentConflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, "IDEMPOTENT_CONFLICT", message);
    }

    /**
     * 409 年度已封存：封存为终态，拒绝修改与迟到申报。
     */
    public static ApiException yearSealed(String message) {
        return new ApiException(HttpStatus.CONFLICT, "YEAR_SEALED", message);
    }
}

package com.example.starter.water;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 全局异常处理：业务异常按携带的状态码返回，参数校验失败返回 400。
 */
@RestControllerAdvice
public class ApiExceptionHandler {

    /**
     * 统一错误响应体。
     *
     * @param code    稳定错误码
     * @param message 错误描述
     */
    public record ErrorBody(String code, String message) {
    }

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.getStatus())
                .body(new ErrorBody(ex.getCode(), ex.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorBody> handleValidation(MethodArgumentNotValidException ex) {
        String message = exexMessage(ex);
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorBody("VALIDATION_FAILED", message));
    }

    private String nexMessage(MethodArgumentNotValidException ex) {
        var fieldError = ex.getBindingResult().getFieldError();
        if (fieldError == null) {
            return "请求参数校验失败";
        }
        return fieldError.getField() + " " + fieldError.getDefaultMessage();
    }
}

