package com.example.starter.water;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * 取水许可水量分配与计量对冲核心服务。
 *
 * <p>规则概要：
 * <ul>
 *   <li>每取水户持年度许可总量，按自然月（UTC）申报，取最后已确认版本；</li>
 *   <li>申报达到许可剩余额度仍可受理，超出即整月拒绝；限取期间新申报减半受理；</li>
 *   <li>申报以 requestId 幂等：同键同参返回首次结果，同键异参返回 409；</li>
 *   <li>计量读数按“计量点＋表底时刻”去重，乱序到达按表底时刻归月；</li>
 *   <li>年度封存为终态：重复封存幂等成功，封存后修改与迟到申报一律拒绝；</li>
 *   <li>封存时超许可部分按 1:1 结转扣减次年额度。</li>
 * </ul>
 *
 * <p>并发约定：申报、限取触发与年度封存均先取 biz_lock 全局行锁（SELECT ... FOR UPDATE），
 * 从而对“限取生效”与“申报受理”形成唯一时间序；申报判定只基于已确认申报快照，
 * 计量读数不参与申报校验。
 */
@Service
public class WaterIntakeService {

    /** 申报状态：已确认。 */
    public static final String STATUS_CONFIRMED = "CONFIRMED";
    /** 申报状态：已拒绝（额度不足整月拒绝）。 */
    public static final String STATUS_REJECTED = "REJECTED";

    private static final BigDecimal TWO = new BigDecimal("2");
    private static final int AMOUNT_SCALE = 3;

    private final JdbcTemplate jdbc;
    private final Clock clock;

    public WaterIntakeService(JdbcTemplate jdbc, Clock businessClock) {
        this.jdbc = jdbc;
        this.clock = businessClock;
    }

    /**
     * 申报受理结果。
     *
     * @param requestId    幂等请求标识
     * @param status       状态：CONFIRMED / REJECTED
     * @param declaredM3   原始申报水量（立方米）
     * @param confirmedM3  实际受理水量（限取减半或拒绝时为受理值）
     * @param restricted   受理时是否处于限取状态
     * @param replayed     是否为幂等重放（返回首次结果）
     */
    public record DeclarationResult(String requestId, String status, BigDecimal declaredM3,
                                    BigDecimal confirmedM3, boolean restricted, boolean replayed) {
    }

    /**
     * 读数入库结果。
     *
     * @param meterPointId 计量点ID
     * @param readingTime  表底时刻（UTC）
     * @param inserted     是否新入库（重复上报为 false，不重累计）
     */
    public record ReadingResult(long meterPointId, Instant readingTime, boolean inserted) {
    }

    /**
     * 限取触发结果。
     *
     * @param riverReachId 河段标识
     * @param active       限取是否生效
     * @param triggeredAt  首次触发时间（UTC）
     * @param replayed     是否为重复触发（幂等）
     */
    public record RestrictionResult(String riverReachId, boolean active, Instant triggeredAt,
                                    boolean replayed) {
    }

    /**
     * 年度封存结果。
     *
     * @param userId           取水户ID
     * @param planYear         封存年度
     * @param sealed           是否已封存（终态）
     * @param actualM3         年度实际取水量（立方米）
     * @param effectiveQuotaM3 年度有效许可量（基准减结转扣减）
     * @param carryoverOutM3   结转扣减次年的水量（立方米，1:1）
     * @param replayed         是否为重复封存（幂等成功）
     */
    public record SealResult(long userId, int planYear, boolean sealed, BigDecimal actualM3,
                             BigDecimal effectiveQuotaM3, BigDecimal carryoverOutM3,
                             boolean replayed) {
    }

    /**
     * 年度账户视图。
     *
     * @param userId           取水户ID
     * @param planYear         年度
     * @param baseQuotaM3      基准许可量
     * @param carryoverInM3    上年结转扣减
     * @param effectiveQuotaM3 有效许可量
     * @param confirmedM3      已确认申报合计（各月最后已确认版本之和）
     * @param actualM3         年度实际取水量（计量累计）
     * @param remainingM3      剩余可申报额度（不扣减计量读数）
     * @param sealed           是否已封存
     */
    public record AnnualAccountView(long userId, int planYear, BigDecimal baseQuotaM3,
                                    BigDecimal carryoverInM3, BigDecimal effectiveQuotaM3,
                                    BigDecimal confirmedM3, BigDecimal actualM3,
                                    BigDecimal remainingM3, boolean sealed) {
    }

    /**
     * 月度计划对冲视图。
     *
     * @param userId      取水户ID
     * @param planYear    年度
     * @param planMonth   月份（1-12）
     * @param confirmedM3 当月最后已确认申报水量
     * @param actualM3    当月实际取水量（按表底时刻归月累计）
     * @param balanceM3   对冲余额（confirmed - actual，可为负表示超采）
     */
    public record MonthPlanView(long userId, int planYear, int planMonth, BigDecimal confirmedM3,
                                BigDecimal actualM3, BigDecimal balanceM3) {
    }

    /** 年度账户行。 */
    private record AnnualAccountRow(long id, long userId, int planYear, BigDecimal baseQuotaM3,
                                    BigDecimal carryoverDeductionM3, BigDecimal carryoverOutM3,
                                    boolean sealed) {
    }

    /**
     * 新建取水户（合成数据）。
     */
    @Transactional
    public long createUser(String name, String riverReachId, BigDecimal annualQuotaM3) {
        jdbc.update("INSERT INTO water_user (name, river_reach_id, annual_quota_m3, created_at)"
                        + " VALUES (?, ?, ?, ?)",
                name, riverReachId, annualQuotaM3, now());
        Long id = jdbc.queryForObject("SELECT MAX(id) FROM water_user WHERE name = ?", Long.class, name);
        return id;
    }

    /**
     * 新建计量点（合成数据）。
     */
    @Transactional
    public long createMeterPoint(long userId, String pointCode, String name) {
        requireUser(userId);
        jdbc.update("INSERT INTO meter_point (user_id, point_code, name, created_at) VALUES (?, ?, ?, ?)",
                userId, pointCode, name, now());
        Long id = jdbc.queryForObject("SELECT id FROM meter_point WHERE point_code = ?", Long.class, pointCode);
        return id;
    }

    /**
     * 提交月度取水计划申报（幂等）。
     *
     * <p>同 requestId 同参数返回首次结果；同 requestId 异参数抛 409 且不产生新版本。
     * 限取生效期间新申报减半受理；已确认计划不受影响。年度封存后一律拒绝。
     */
    @Transactional
    public DeclarationResult declare(String requestId, long userId, int planYear, int planMonth,
                                     BigDecimal declaredM3) {
        String fingerprint = fingerprint(requestId, userId, planYear, planMonth, declaredM3);
        List<Map<String, Object>> existing = jdbc.queryForList(
                "SELECT fingerprint, status, declared_m3, confirmed_m3, restricted"
                        + " FROM plan_declaration WHERE request_id = ?", requestId);
        if (!existing.isEmpty()) {
            Map<String, Object> row = existing.get(0);
            if (!fingerprint.equals(row.get("FINGERPRINT"))) {
                throw ApiException.idempotentConflict(
                        "requestId 已存在但申报参数不同，拒绝产生新版本: " + requestId);
            }
            return new DeclarationResult(requestId, (String) row.get("STATUS"),
                    (BigDecimal) row.get("DECLARED_M3"), (BigDecimal) row.get("CONFIRMED_M3"),
                    toBool(row.get("RESTRICTED")), true);
        }

        requireUser(userId);
        lockGlobal();

        AnnualAccountRow account = findAccount(userId, planYear);
        if (account != null && account.sealed()) {
            throw ApiException.yearSealed("年度 " + planYear + " 已封存，拒绝申报: userId=" + userId);
        }
        if (account == null) {
            account = createAccount(userId, planYear, BigDecimal.ZERO);
        }

        boolean restricted = isRestricted(userId);
        BigDecimal effectiveRequest = restricted
                ? declaredM3.divide(TWO, AMOUNT_SCALE, RoundingMode.HALF_UP)
                : declaredM3;

        BigDecimal remaining = effectiveQuota(account).subtract(confirmedTotal(userId, planYear));
        String status;
        BigDecimal confirmed;
        if (effectiveRequest.compareTo(remaining) <= 0) {
            status = STATUS_CONFIRMED;
            confirmed = effectiveRequest;
        } else {
            status = STATUS_REJECTED;
            confirmed = BigDecimal.ZERO.setScale(AMOUNT_SCALE, RoundingMode.HALF_UP);
        }

        jdbc.update("INSERT INTO plan_declaration (request_id, fingerprint, user_id, plan_year,"
                        + " plan_month, declared_m3, confirmed_m3, status, restricted, created_at)"
                        + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                requestId, fingerprint, userId, planYear, planMonth, declaredM3, confirmed,
                status, restricted ? 1 : 0, now());
        return new DeclarationResult(requestId, status, declaredM3, confirmed, restricted, false);
    }

    /**
     * 上报计量读数（按计量点＋表底时刻去重，重复上报幂等成功且不重累计）。
     */
    @Transactional
    public ReadingResult reportReading(long meterPointId, Instant readingTime,
                                       BigDecimal readingValueM3) {
        Integer count = jdbc.queryForObject("SELECT COUNT(*) FROM meter_point WHERE id = ?",
                Integer.class, meterPointId);
        if (count == null || count == 0) {
            throw ApiException.notFound("计量点不存在: " + meterPointId);
        }
        try {
            jdbc.update("INSERT INTO meter_reading (meter_point_id, reading_time, reading_value_m3,"
                            + " received_at) VALUES (?, ?, ?, ?)",
                    meterPointId, Timestamp.from(readingTime), readingValueM3, now());
            return new ReadingResult(meterPointId, readingTime, true);
        } catch (DuplicateKeyException duplicate) {
            return new ReadingResult(meterPointId, readingTime, false);
        }
    }

    /**
     * 触发河段生态流量限取（幂等）。与申报并发时按全局锁形成唯一时间序。
     */
    @Transactional
    public RestrictionResult triggerRestriction(String riverReachId) {
        lockGlobal();
        List<Map<String, Object>> rows = jdbc.queryForList(
                "SELECT active, triggered_at FROM reach_restriction WHERE river_reach_id = ?",
                riverReachId);
        if (!rows.isEmpty()) {
            Map<String, Object> row = rows.get(0);
            if (toBool(row.get("ACTIVE"))) {
                return new RestrictionResult(riverReachId, true, toInstant(row.get("TRIGGERED_AT")), true);
            }
            jdbc.update("UPDATE reach_restriction SET active = 1, triggered_at = ?, updated_at = ?"
                    + " WHERE river_reach_id = ?", now(), now(), riverReachId);
        } else {
            jdbc.update("INSERT INTO reach_restriction (river_reach_id, active, triggered_at, updated_at)"
                    + " VALUES (?, 1, ?, ?)", riverReachId, now(), now());
        }
        Instant triggeredAt = jdbc.queryForObject(
                "SELECT triggered_at FROM reach_restriction WHERE river_reach_id = ?",
                Instant.class, riverReachId);
        return new RestrictionResult(riverReachId, true, triggeredAt, false);
    }

    /**
     * 封存年度计划（终态，重复调用幂等成功）。
     *
     * <p>封存时按计量读数累计年度实际取水量，超有效许可部分按 1:1 结转扣减次年额度；
     * 次年账户不存在则创建，已存在则更新其结转扣减。
     */
    @Transactional
    public SealResult sealAnnualAccount(long userId, int planYear) {
        requireUser(userId);
        lockGlobal();

        AnnualAccountRow account = findAccountForUpdate(userId, planYear);
        if (account != null && account.sealed()) {
            return new SealResult(userId, planYear, true, annualActual(userId, planYear),
                    effectiveQuota(account), account.carryoverOutM3(), true);
        }
        if (account == null) {
            account = createAccount(userId, planYear, BigDecimal.ZERO);
        }

        BigDecimal actual = annualActual(userId, planYear);
        BigDecimal effective = effectiveQuota(account);
        BigDecimal excess = actual.subtract(effective).max(BigDecimal.ZERO)
                .setScale(AMOUNT_SCALE, RoundingMode.HALF_UP);

        jdbc.update("UPDATE annual_account SET sealed = 1, sealed_at = ?, carryover_out_m3 = ?"
                + " WHERE id = ?", now(), excess, account.id());

        AnnualAccountRow next = findAccountForUpdate(userId, planYear + 1);
        if (next == null) {
            createAccount(userId, planYear + 1, excess);
        } else {
            jdbc.update("UPDATE annual_account SET carryover_deduction_m3 = ? WHERE id = ?",
                    excess, next.id());
        }
        return new SealResult(userId, planYear, true, actual, effective, excess, false);
    }

    /**
     * 查询年度账户视图。账户尚未产生时按基准许可量返回未封存视图。
     */
    @Transactional(readOnly = true)
    public AnnualAccountView getAnnualAccount(long userId, int planYear) {
        BigDecimal baseQuota = requireUser(userId);
        AnnualAccountRow account = findAccount(userId, planYear);
        BigDecimal base = account == null ? baseQuota : account.baseQuotaM3();
        BigDecimal carryoverIn = account == null ? BigDecimal.ZERO : account.carryoverDeductionM3();
        BigDecimal effective = base.subtract(carryoverIn);
        BigDecimal confirmed = confirmedTotal(userId, planYear);
        BigDecimal actual = annualActual(userId, planYear);
        boolean sealed = account != null && account.sealed();
        return new AnnualAccountView(userId, planYear, base, carryoverIn, effective, confirmed,
                actual, effective.subtract(confirmed), sealed);
    }

    /**
     * 查询月度计划对冲视图。
     */
    @Transactional(readOnly = true)
    public MonthPlanView getMonthPlan(long userId, int planYear, int planMonth) {
        requireUser(userId);
        BigDecimal confirmed = latestConfirmedForMonth(userId, planYear, planMonth);
        BigDecimal actual = monthActual(userId, planYear, planMonth);
        return new MonthPlanView(userId, planYear, planMonth, confirmed, actual,
                confirmed.subtract(actual));
    }

    // ---------- 内部辅助 ----------

    private Timestamp now() {
        return Timestamp.from(clock.instant());
    }

    private BigDecimal requireUser(long userId) {
        List<BigDecimal> quotas = jdbc.queryForList(
                "SELECT annual_quota_m3 FROM water_user WHERE id = ?", BigDecimal.class, userId);
        if (quotas.isEmpty()) {
            throw ApiException.notFound("取水户不存在: " + userId);
        }
        return quotas.get(0);
    }

    /** 取全局定序行锁（SELECT ... FOR UPDATE），序列化申报/限取/封存。 */
    private void lockGlobal() {
        jdbc.queryForList("SELECT lock_key FROM biz_lock WHERE lock_key = 'GLOBAL' FOR UPDATE");
    }

    private AnnualAccountRow findAccount(long userId, int planYear) {
        List<AnnualAccountRow> rows = jdbc.query(
                "SELECT id, user_id, plan_year, base_quota_m3, carryover_deduction_m3,"
                        + " carryover_out_m3, sealed FROM annual_account"
                        + " WHERE user_id = ? AND plan_year = ?",
                (rs, rowNum) -> new AnnualAccountRow(rs.getLong("id"), rs.getLong("user_id"),
                        rs.getInt("plan_year"), rs.getBigDecimal("base_quota_m3"),
                        rs.getBigDecimal("carryover_deduction_m3"),
                        rs.getBigDecimal("carryover_out_m3"), rs.getBoolean("sealed")),
                userId, planYear);
        return rows.isEmpty() ? null : rows.get(0);
    }

    private AnnualAccountRow findAccountForUpdate(long userId, int planYear) {
        List<AnnualAccountRow> rows = jdbc.query(
                "SELECT id, user_id, plan_year, base_quota_m3, carryover_deduction_m3,"
                        + " carryover_out_m3, sealed FROM annual_account"
                        + " WHERE user_id = ? AND plan_year = ? FOR UPDATE",
                (rs, rowNum) -> new AnnualAccountRow(rs.getLong("id"), rs.getLong("user_id"),
                        rs.getInt("plan_year"), rs.getBigDecimal("base_quota_m3"),
                        rs.getBigDecimal("carryover_deduction_m3"),
                        rs.getBigDecimal("carryover_out_m3"), rs.getBoolean("sealed")),
                userId, planYear);
        return rows.isEmpty() ? null : rows.get(0);
    }

    private AnnualAccountRow createAccount(long userId, int planYear, BigDecimal carryoverIn) {
        BigDecimal baseQuota = requireUser(userId);
        jdbc.update("INSERT INTO annual_account (user_id, plan_year, base_quota_m3,"
                        + " carryover_deduction_m3, sealed, created_at) VALUES (?, ?, ?, ?, 0, ?)",
                userId, planYear, baseQuota, carryoverIn, now());
        return findAccount(userId, planYear);
    }

    private BigDecimal effectiveQuota(AnnualAccountRow account) {
        return account.baseQuotaM3().subtract(account.carryoverDeductionM3());
    }

    private boolean isRestricted(long userId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM reach_restriction r JOIN water_user u"
                        + " ON r.river_reach_id = u.river_reach_id"
                        + " WHERE u.id = ? AND r.active = 1",
                Integer.class, userId);
        return count != null && count > 0;
    }

    /** 年度已确认申报合计：每月取最后一条 CONFIRMED 版本后求和。 */
    private BigDecimal confirmedTotal(long userId, int planYear) {
        List<Map<String, Object>> rows = jdbc.queryForList(
                "SELECT plan_month, confirmed_m3 FROM plan_declaration"
                        + " WHERE user_id = ? AND plan_year = ? AND status = 'CONFIRMED'"
                        + " ORDER BY id",
                userId, planYear);
        Map<Integer, BigDecimal> latestByMonth = new HashMap<>();
        for (Map<String, Object> row : rows) {
            latestByMonth.put(((Number) row.get("PLAN_MONTH")).intValue(),
                    (BigDecimal) row.get("CONFIRMED_M3"));
        }
        return latestByMonth.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    /** 当月最后已确认申报水量；无确认为 0。 */
    private BigDecimal latestConfirmedForMonth(long userId, int planYear, int planMonth) {
        List<BigDecimal> rows = jdbc.queryForList(
                "SELECT confirmed_m3 FROM plan_declaration"
                        + " WHERE user_id = ? AND plan_year = ? AND plan_month = ?"
                        + " AND status = 'CONFIRMED' ORDER BY id DESC LIMIT 1",
                BigDecimal.class, userId, planYear, planMonth);
        return rows.isEmpty() ? BigDecimal.ZERO.setScale(AMOUNT_SCALE, RoundingMode.HALF_UP)
                : rows.get(0);
    }

    /** 年度实际取水量：逐月累计（按表底时刻归月）。 */
    private BigDecimal annualActual(long userId, int planYear) {
        BigDecimal total = BigDecimal.ZERO;
        for (int month = 1; month <= 12; month++) {
            total = total.add(monthActual(userId, planYear, month));
        }
        return total.setScale(AMOUNT_SCALE, RoundingMode.HALF_UP);
    }

    /**
     * 单月实际取水量：对每个计量点取“月内最大表底 - 月初基线”。
     * 基线为月初前最近表底；若月初前无读数，则以月内最小表底为基线（自首表起算）。
     * 读数乱序到达不影响结果，因为只依赖表底时刻。
     */
    private BigDecimal monthActual(long userId, int planYear, int planMonth) {
        LocalDate firstDay = LocalDate.of(planYear, planMonth, 1);
        Instant monthStart = firstDay.atStartOfDay().toInstant(ZoneOffset.UTC);
        Instant monthEnd = firstDay.plusMonths(1).atStartOfDay().toInstant(ZoneOffset.UTC);

        List<Long> pointIds = jdbc.queryForList(
                "SELECT id FROM meter_point WHERE user_id = ?", Long.class, userId);
        BigDecimal total = BigDecimal.ZERO;
        for (Long pointId : pointIds) {
            BigDecimal maxInMonth = queryNullableBigDecimal(
                    "SELECT MAX(reading_value_m3) FROM meter_reading"
                            + " WHERE meter_point_id = ? AND reading_time >= ? AND reading_time < ?",
                    pointId, Timestamp.from(monthStart), Timestamp.from(monthEnd));
            if (maxInMonth == null) {
                continue;
            }
            BigDecimal baseline = queryNullableBigDecimal(
                    "SELECT MAX(reading_value_m3) FROM meter_reading"
                            + " WHERE meter_point_id = ? AND reading_time < ?",
                    pointId, Timestamp.from(monthStart));
            if (baseline == null) {
                baseline = queryNullableBigDecimal(
                        "SELECT MIN(reading_value_m3) FROM meter_reading"
                                + " WHERE meter_point_id = ? AND reading_time >= ? AND reading_time < ?",
                        pointId, Timestamp.from(monthStart), Timestamp.from(monthEnd));
            }
            total = total.add(maxInMonth.subtract(baseline));
        }
        return total;
    }

    private BigDecimal queryNullableBigDecimal(String sql, Object... args) {
        List<BigDecimal> rows = jdbc.queryForList(sql, BigDecimal.class, args);
        return rows.isEmpty() ? null : rows.get(0);
    }

    private static String fingerprint(String requestId, long userId, int planYear, int planMonth,
                                      BigDecimal declaredM3) {
        String material = String.join("|", requestId, String.valueOf(userId),
                String.valueOf(planYear), String.valueOf(planMonth), declaredM3.toPlainString());
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(material.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(hash.length * 2);
            for (byte b : hash) {
                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
                hex.append(Character.forDigit(b & 0xF, 16));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }

    private static boolean toBool(Object value) {
        if (value instanceof Boolean bool) {
            return bool;
        }
        return ((Number) value).intValue() != 0;
    }

    private static Instant toInstant(Object value) {
        if (value instanceof Timestamp ts) {
            return ts.toInstant();
        }
        return ((java.time.LocalDateTime) value).toInstant(ZoneOffset.UTC);
    }
}

