package com.example.starter.water;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;
import java.util.UUID;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 取水许可业务主流程与失败分支测试（H2 MODE=MySQL 实测，含唯一约束与事务边界）。
 */
@SpringBootTest
class WaterIntakeServiceTest {

    @Autowired
    private WaterIntakeService service;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void cleanTables() {
        jdbc.update("DELETE FROM meter_reading");
        jdbc.update("DELETE FROM meter_point");
        jdbc.update("DELETE FROM plan_declaration");
        jdbc.update("DELETE FROM annual_account");
        jdbc.update("DELETE FROM reach_restriction");
        jdbc.update("DELETE FROM water_user");
    }

    private long newUser(String reach, String quota) {
        return service.createUser("户-" + UUID.randomUUID(), reach, new BigDecimal(quota));
    }

    private String reqId() {
        return "req-" + UUID.randomUUID();
    }

    @Test
    void 额满边界_达到剩余额度仍受理_超出即整月拒绝() {
        long user = newUser("R1", "1000");

        var first = service.declare(reqId(), user, 2026, 1, new BigDecimal("600"));
        assertThat(first.status()).isEqualTo(WaterIntakeService.STATUS_CONFIRMED);
        assertThat(first.confirmedM3()).isEqualByComparingTo("600");

        // 剩余额度恰好 400，达到仍可受理
        var second = service.declare(reqId(), user, 2026, 2, new BigDecimal("400"));
        assertThat(second.status()).isEqualTo(WaterIntakeService.STATUS_CONFIRMED);
        assertThat(second.confirmedM3()).isEqualByComparingTo("400");

        // 超出剩余额度（为 0），整月拒绝
        var third = service.declare(reqId(), user, 2026, 3, new BigDecimal("0.001"));
        assertThat(third.status()).isEqualTo(WaterIntakeService.STATUS_REJECTED);
        assertThat(third.confirmedM3()).isEqualByComparingTo("0");

        var view = service.getAnnualAccount(user, 2026);
        assertThat(view.confirmedM3()).isEqualByComparingTo("1000");
        assertThat(view.remainingM3()).isEqualByComparingTo("0");
    }

    @Test
    void 月计划多次修改_取最后已确认版本() {
        long user = newUser("R1", "1000");

        service.declare(reqId(), user, 2026, 1, new BigDecimal("600"));
        service.declare(reqId(), user, 2026, 1, new BigDecimal("700"));
        // 拒绝的版本不覆盖已确认版本
        var rejected = service.declare(reqId(), user, 2026, 1, new BigDecimal("1200"));
        assertThat(rejected.status()).isEqualTo(WaterIntakeService.STATUS_REJECTED);
        service.declare(reqId(), user, 2026, 1, new BigDecimal("300"));

        var month = service.getMonthPlan(user, 2026, 1);
        assertThat(month.confirmedM3()).isEqualByComparingTo("300");
        var view = service.getAnnualAccount(user, 2026);
        assertThat(view.confirmedM3()).isEqualByComparingTo("300");
    }

    @Test
    void 申报判定基于已确认额度快照_读数不参与申报校验() {
        long user = newUser("R1", "1000");
        long point = service.createMeterPoint(user, "P-" + UUID.randomUUID(), "一号表");

        // 实际取水已远超许可，但申报校验只看已确认申报快照
        service.reportReading(point, Instant.parse("2026-01-01T00:00:00Z"), new BigDecimal("0"));
        service.reportReading(point, Instant.parse("2026-03-10T00:00:00Z"), new BigDecimal("5000"));

        var result = service.declare(reqId(), user, 2026, 4, new BigDecimal("1000"));
        assertThat(result.status()).isEqualTo(WaterIntakeService.STATUS_CONFIRMED);
        assertThat(result.confirmedM3()).isEqualByComparingTo("1000");
    }

    @Test
    void 超限结转_封存时按1比1扣减次年额度() {
        long user = newUser("R1", "1000");
        long point = service.createMeterPoint(user, "P-" + UUID.randomUUID(), "一号表");
        service.reportReading(point, Instant.parse("2026-01-01T00:00:00Z"), new BigDecimal("0"));
        service.reportReading(point, Instant.parse("2026-06-15T00:00:00Z"), new BigDecimal("1200"));

        var seal = service.sealAnnualAccount(user, 2026);
        assertThat(seal.sealed()).isTrue();
        assertThat(seal.actualM3()).isEqualByComparingTo("1200");
        assertThat(seal.effectiveQuotaM3()).isEqualByComparingTo("1000");
        assertThat(seal.carryoverOutM3()).isEqualByComparingTo("200");

        var nextYear = service.getAnnualAccount(user, 2027);
        assertThat(nextYear.baseQuotaM3()).isEqualByComparingTo("1000");
        assertThat(nextYear.carryoverInM3()).isEqualByComparingTo("200");
        assertThat(nextYear.effectiveQuotaM3()).isEqualByComparingTo("800");

        // 次年有效额度 800：达到可受理，超出拒绝
        var ok = service.declare(reqId(), user, 2027, 1, new BigDecimal("800"));
        assertThat(ok.status()).isEqualTo(WaterIntakeService.STATUS_CONFIRMED);
        var over = service.declare(reqId(), user, 2027, 2, new BigDecimal("0.001"));
        assertThat(over.status()).isEqualTo(WaterIntakeService.STATUS_REJECTED);
    }

    @Test
    void 限取减半_新申报减半受理_已确认计划不变() {
        long restricted = newUser("R-ECO", "1000");
        long normal = newUser("R-OTHER", "1000");

        var before = service.declare(reqId(), restricted, 2026, 1, new BigDecimal("100"));
        assertThat(before.confirmedM3()).isEqualByComparingTo("100");

        var trigger = service.triggerRestriction("R-ECO");
        assertThat(trigger.active()).isTrue();
        assertThat(trigger.replayed()).isFalse();

        var halved = service.declare(reqId(), restricted, 2026, 2, new BigDecimal("100"));
        assertThat(halved.restricted()).isTrue();
        assertThat(halved.status()).isEqualTo(WaterIntakeService.STATUS_CONFIRMED);
        assertThat(halved.confirmedM3()).isEqualByComparingTo("50");

        // 已确认计划不变
        var january = service.getMonthPlan(restricted, 2026, 1);
        assertThat(january.confirmedM3()).isEqualByComparingTo("100");

        // 未受影响河段全额受理
        var unaffected = service.declare(reqId(), normal, 2026, 2, new BigDecimal("100"));
        assertThat(unaffected.restricted()).isFalse();
        assertThat(unaffected.confirmedM3()).isEqualByComparingTo("100");

        // 重复触发幂等
        var again = service.triggerRestriction("R-ECO");
        assertThat(again.replayed()).isTrue();
        assertThat(again.triggeredAt()).isEqualTo(trigger.triggeredAt());
    }

    @Test
    void 幂等_同键同参返回首次结果_同键异参409且不产生新版本() {
        long user = newUser("R1", "1000");
        String requestId = reqId();

        var first = service.declare(requestId, user, 2026, 1, new BigDecimal("100"));
        assertThat(first.replayed()).isFalse();

