import java.util.UUID;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 并发与竞态测试：真实多线程并发，协调同时起跑并设置超时，
 * 断言业务结果与最终数据一致性。
 */
@SpringBootTest
class WaterIntakeConcurrencyTest {

    private static final int THREADS = 10;

    @Autowired
    private WaterIntakeService service;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void cleanTables() {
        jdbc.update("DELETE FROM meter_reading");
        jdbc.update("DELETE FROM meter_point");
        jdbc.update("DELETE FROM plan_declaration");
        jdbc.update("DELETE FROM annual_account");
        jdbc.update("DELETE FROM reach_restriction");
        jdbc.update("DELETE FROM water_user");
    }

    @Test
    void 并发申报_同一取水户各自正确_确认总额不超许可() throws Exception {
        long user = service.createUser("并发户", "R-C", new BigDecimal("1000"));

        ExecutorService pool = Executors.newFixedThreadPool(THREADS);
        CountDownLatch ready = new CountDownLatch(THREADS);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<WaterIntakeService.DeclarationResult>> futures = new ArrayList<>();
        for (int i = 1; i <= THREADS; i++) {
            final int month = i;
            futures.add(pool.submit(() -> {
                ready.countDown();
                assertThat(start.await(10, TimeUnit.SECONDS)).isTrue();
                return service.declare("race-req-" + month, user, 2026, month,
                        new BigDecimal("200"));
            }));
        }
        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
        start.countDown();

        int confirmed = 0;
        int rejected = 0;
        for (Future<WaterIntakeService.DeclarationResult> future : futures) {
            var result = future.get(30, TimeUnit.SECONDS);
            if (WaterIntakeService.STATUS_CONFIRMED.equals(result.status())) {
                confirmed++;
                assertThat(result.confirmedM3()).isEqualByComparingTo("200");
            } else {
                rejected++;
                assertThat(result.confirmedM3()).isEqualByComparingTo("0");
            }
        }
        pool.shutdown();
        assertThat(pool.awaitTermination(10, TimeUnit.SECONDS)).isTrue();

        // 许可 1000、每单 200：恰好 5 单确认、5 单拒绝，确认总额不超许可
        assertThat(confirmed).isEqualTo(5);
        assertThat(rejected).isEqualTo(5);
        var view = service.getAnnualAccount(user, 2026);
        assertThat(view.confirmedM3()).isEqualByComparingTo("1000");
        assertThat(view.remainingM3()).isEqualByComparingTo("0");
    }

    @Test
    void 限取触发与申报并发_按时间先后形成唯一结果() throws Exception {
        int fullBeforeRestriction = 0;
        int halvedAfterRestriction = 0;

        for (int round = 0; round < 20; round++) {
            String reach = "R-RACE-" + round;
            long user = service.createUser("竞态户-" + round, reach, new BigDecimal("1000"));
            String requestId = "race-req-" + round;

            ExecutorService pool = Executors.newFixedThreadPool(2);
            CountDownLatch ready = new CountDownLatch(2);
            CountDownLatch start = new CountDownLatch(1);
            Future<WaterIntakeService.RestrictionResult> triggerFuture = pool.submit(() -> {
                ready.countDown();
                start.await(10, TimeUnit.SECONDS);
                return service.triggerRestriction(reach);
            });
