 * 并发与竞态测试：真实多线程并发，协调同时起跑并设置超时，
 * 断言业务结果与最终数据一致性。
 */
@SpringBootTest
class WaterIntakeConcurrencyTest {

    private static final int THREADS = 10;

    @Autowired
    private WaterIntakeService service;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void cleanTables() {
        jdbc.update("DELETE FROM meter_reading");
        jdbc.update("DELETE FROM meter_point");
