            assertThat(pool.awaitTermination(10, TimeUnit.SECONDS)).isTrue();

            assertThat(trigger.active()).isTrue();
            assertThat(declaration.status()).isEqualTo(WaterIntakeService.STATUS_CONFIRMED);
            if (declaration.restricted()) {
                // 限取先生效：必须减半受理，不得按全额
                assertThat(declaration.confirmedM3()).isEqualByComparingTo("50");
                halvedAfterRestriction++;
            } else {
                // 申报先受理：全额确认，且之后触发限取不得改判已确认计划
                assertThat(declaration.confirmedM3()).isEqualByComparingTo("100");
                fullBeforeRestriction++;
            }

            // 无论哪种时序，结果唯一且可重放
            var replay = service.declare(requestId, user, 2026, 6, new BigDecimal("100"));
            assertThat(replay.replayed()).isTrue();
            assertThat(replay.confirmedM3()).isEqualByComparingTo(declaration.confirmedM3());
            assertThat(replay.restricted()).isEqualTo(declaration.restricted());
            var month = service.getMonthPlan(user, 2026, 6);
            assertThat(month.confirmedM3()).isEqualByComparingTo(declaration.confirmedM3());
        }
        // 至少出现一种合法时序（两种均合法，不强制各半）
        assertThat(fullBeforeRestriction + halvedAfterRestriction).isEqualTo(20);
    }

    @Test
    void 并发读数上报_同表底时刻仅入库一次() throws Exception {
        long user = service.createUser("读数户", "R-M", new BigDecimal("10000"));
        long point = service.createMeterPoint(user, "PM-" + UUID.randomUUID(), "一号表");
        Instant readingTime = Instant.parse("2026-04-15T08:00:00Z");

        ExecutorService pool = Executors.newFixedThreadPool(THREADS);
        CountDownLatch ready = new CountDownLatch(THREADS);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<WaterIntakeService.ReadingResult>> futures = new ArrayList<>();
        for (int i = 0; i < THREADS; i++) {
            futures.add(pool.submit(() -> {
                ready.countDown();
                start.await(10, TimeUnit.SECONDS);
                return service.reportReading(point, readingTime, new BigDecimal("250"));
            }));
        }
        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
        start.countDown();

        int inserted = 0;
        for (Future<WaterIntakeService.ReadingResult> future : futures) {
            if (future.get(30, TimeUnit.SECONDS).inserted()) {
                inserted++;
            }
        }
        pool.shutdown();
        assertThat(pool.awaitTermination(10, TimeUnit.SECONDS)).isTrue();

        assertThat(inserted).isEqualTo(1);
        Integer count = jdbc.queryForObject(
