package com.example.starter.water;

import static org.hamcrest.Matchers.is;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.UUID;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;

/**
 * REST 入口 HTTP 语义测试：状态码、错误码与公开主流程。
 */
@SpringBootTest
@AutoConfigureMockMvc
class WaterIntakeApiTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void cleanTables() {
        jdbc.update("DELETE FROM meter_reading");
        jdbc.update("DELETE FROM meter_point");
        jdbc.update("DELETE FROM plan_declaration");
        jdbc.update("DELETE FROM annual_account");
        jdbc.update("DELETE FROM reach_restriction");
        jdbc.update("DELETE FROM water_user");
    }

    private long createUser(String reach, String quota) throws Exception {
        String body = "{\"name\":\"户-" + UUID.randomUUID() + "\",\"riverReachId\":\"" + reach
                + "\",\"annualQuotaM3\":" + quota + "}";
        String response = mockMvc.perform(post("/api/water/users")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.id").isNumber())
                .andReturn().getResponse().getContentAsString();
        return Long.parseLong(response.replaceAll("[^0-9]", ""));
    }

    @Test
    void 申报主流程与幂等冲突的HTTP语义() throws Exception {
        long user = createUser("R-API", "1000");

        String declare = "{\"requestId\":\"api-req-1\",\"userId\":" + user
                + ",\"planYear\":2026,\"planMonth\":1,\"declaredM3\":100}";
        mockMvc.perform(post("/api/water/declarations")
                        .contentType(MediaType.APPLICATION_JSON).content(declare))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status", is("CONFIRMED")))
                .andExpect(jsonPath("$.confirmedM3", is(100)))
                .andExpect(jsonPath("$.replayed", is(false)));

        // 同键同参：重放首次结果
        mockMvc.perform(post("/api/water/declarations")
                        .contentType(MediaType.APPLICATION_JSON).content(declare))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.replayed", is(true)))
                .andExpect(jsonPath("$.confirmedM3", is(100)));

        // 同键异参：409 IDEMPOTENT_CONFLICT
        String conflict = "{\"requestId\":\"api-req-1\",\"userId\":" + user
                + ",\"planYear\":2026,\"planMonth\":1,\"declaredM3\":200}";
        mockMvc.perform(post("/api/water/declarations")
                        .contentType(MediaType.APPLICATION_JSON).content(conflict))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code", is("IDEMPOTENT_CONFLICT")));

        // 参数校验失败：400
        String invalid = "{\"requestId\":\"api-req-2\",\"userId\":" + user
                + ",\"planYear\":2026,\"planMonth\":13,\"declaredM3\":100}";
        mockMvc.perform(post("/api/water/declarations")
                        .contentType(MediaType.APPLICATION_JSON).content(invalid))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.code", is("VALIDATION_FAILED")));

        // 不存在的取水户：404
        String notFound = "{\"requestId\":\"api-req-3\",\"userId\":999999"
                + ",\"planYear\":2026,\"planMonth\":1,\"declaredM3\":100}";
        mockMvc.perform(post("/api/water/declarations")
                        .contentType(MediaType.APPLICATION_JSON).content(notFound))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code", is("NOT_FOUND")));
    }

    @Test
    void 封存后申报返回409且年度账户可查() throws Exception {
        long user = createUser("R-API", "1000");

        mockMvc.perform(post("/api/water/annual-accounts/{userId}/{year}/seal", user, 2026))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sealed", is(true)))
                .andExpect(jsonPath("$.carryoverOutM3", is(0)));

        // 重复封存幂等成功
        mockMvc.perform(post("/api/water/annual-accounts/{userId}/{year}/seal", user, 2026))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.replayed", is(true)));

        String late = "{\"requestId\":\"api-req-late\",\"userId\":" + user
                + ",\"planYear\":2026,\"planMonth\":3,\"declaredM3\":100}";
        mockMvc.perform(post("/api/water/declarations")
                        .contentType(MediaType.APPLICATION_JSON).content(late))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code", is("YEAR_SEALED")));

        mockMvc.perform(get("/api/water/annual-accounts/{userId}/{year}", user, 2026))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.sealed", is(true)))
                .andExpect(jsonPath("$.effectiveQuotaM3", is(1000)));
    }

    @Test
    void 限取触发后新申报减半() throws Exception {
        long user = createUser("R-API-ECO", "1000");

        mockMvc.perform(post("/api/water/restrictions/trigger")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"riverReachId\":\"R-API-ECO\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.active", is(true)));

        String declare = "{\"requestId\":\"api-req-eco\",\"userId\":" + user
                + ",\"planYear\":2026,\"planMonth\":2,\"declaredM3\":100}";
        mockMvc.perform(post("/api/water/declarations")
                        .contentType(MediaType.APPLICATION_JSON).content(declare))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.restricted", is(true)))
                .andExpect(jsonPath("$.confirmedM3", is(50)));
    }
}

